async function obtenerProducto(id) {
  const clave = `producto:${id}`;
  const enCache = await redis.get(clave);
  if (enCache) return JSON.parse(enCache);            // acierto

  const producto = await db.productos.findById(id);   // fallo
  await redis.set(clave, JSON.stringify(producto), { EX: 300 }); // TTL 5 min
  return producto;
}

const categorias = new Map();

function obtenerCategoria(datos) {
  if (!categorias.has(datos.id)) {
    categorias.set(datos.id, Object.freeze({ ...datos }));
  }
  return categorias.get(datos.id);
}

const productos = filas.map((f) => ({
  id: f.id,
  precio: f.precio,
  categoria: obtenerCategoria(f.categoria)  // compartida
}));
